function createLazyComponent<T extends ComponentType<any>>(
    factory: () => Promise<{ default: T }>
) {
    const LazyComponent = lazy(factory)

    return (props: React.ComponentProps<T>) => {
        const [isMounted, setIsMounted] = useState(false)

        useEffect(() => {
            setIsMounted(true)
        }, [])

        if (!isMounted) {
            return null
        }

        return (
            <Suspense>
                <LazyComponent {...props} />
            </Suspense>
        )
    }
}

