  exportOperator: async (payload: ReportExportRequest): Promise<ReportExportResult> => {
    try {
      const response = await axios.get<ArrayBuffer>(
        `${API_BASE_URL}${ENDPOINTS.REPORT.OPERATOR_EXPORT}`,
        {
          headers: {
            Authorization: `Bearer ${payload.token}`,
            ...buildRequestSecurityHeaders({}),
          },
          params: {
            from: payload.from,
            to: payload.to,
            period: payload.period,
          },
          responseType: 'arraybuffer',
          timeout: 30000,
        },
      )

      const contentDisposition = response.headers['content-disposition'] as string | undefined
      const contentType = (response.headers['content-type'] as string | undefined) ?? ''
      const filename = getFilenameFromHeaders(contentDisposition, contentType, payload)
      const defaultDirectory = app.getPath('downloads')
      const defaultPath = path.join(defaultDirectory, filename)

      await writeFile(defaultPath, Buffer.from(response.data))

      return {
        filename,
        savedPath: defaultPath,
      }
    } catch (error) {
      if (axios.isAxiosError(error)) {
        const statusCode = error.response?.status
        const apiMessage =
          (error.response?.data as { message?: string } | undefined)?.message ||
          error.message ||
          'Gagal mengunduh laporan operator'

        throw new Error(statusCode ? `HTTP_STATUS_${statusCode}::${apiMessage}` : apiMessage)
      }
      throw error
    }
  },
}

// src/renderer/src/lib/validate-image-dimension.ts
export interface ImageDimensionConstraint {
  minWidth: number
  minHeight: number
  maxWidth: number
  maxHeight: number
}

export const validateImageDimension = (
  imageSrc: string,
  constraint: ImageDimensionConstraint
): Promise<boolean> =>
  new Promise((resolve) => {
    const img = new Image()
    img.onload = () => {
      const isValidDimension =
        img.width >= constraint.minWidth &&
        img.height >= constraint.minHeight &&
        img.width <= constraint.maxWidth &&
        img.height <= constraint.maxHeight
      resolve(isValidDimension)
    }
    img.onerror = () => resolve(false)
    img.src = imageSrc
  })
